CASES=[('case-sales','매출과 수익','매출이 줄었는데, 어디부터 볼까요?','문의·구매·객단가·환불, 상품·가격·광고 변경과 같은 기간의 영업일을 봅니다.','경기 외에도 문의 감소, 안내의 변화, 결제와 제공 시점 차이가 있을 수 있습니다.','한 상품의 문의부터 구매까지 같은 기준으로 기록하고, 가장 달라진 구간을 정리합니다.','문의·구매의 정의와 기간을 맞춘 집계, 원가와 환불. 자료가 부족하면 원인을 유보합니다.'),('case-away','대표 부재 운영','자리를 비워도 업무가 이어지려면.','대표 부재 중 연락 한 장면, 기존 승인 기준, 담당자가 갖고 있던 정보를 봅니다.','담당자가 기준을 찾지 못했거나 결정 범위를 다르게 이해했을 수 있습니다. 대표 판단이 필요한 예외는 구분합니다.','한 업무의 처리·승인표를 정리하고 실제 사용자의 이해와 사용 여부를 확인합니다.','비긴급 확인 연락, 미처리, 잘못된 안내를 함께 봅니다. 연락이 줄어도 고객 혼선이 늘면 수정합니다.'),('case-team','역할과 인계','서로 자기 일이 아니라고 생각할 때.','같은 요청의 대표·담당자 설명, 역할·인계 기준, 완료까지 남은 기록을 대조합니다.','담당이 비어 있거나 완료의 뜻이 다를 수 있습니다. 특정 직원의 태도로 바로 결론 내리지 않습니다.','한 업무의 담당·승인·인계·완료 기준과 교대 양식을 정리합니다.','담당 미정 요청, 인계 누락, 재작업과 실제 양식 사용. 개인 평가·감시 용도로 바뀌면 목적을 다시 확인합니다.'),('case-brand','브랜드와 고객 안내','잘하는 일과 소개글이 다를 때.','상품·제공 과정, 소개글·메뉴·상담 문구, 고객이 설명한 선택 이유를 살핍니다.','강점이 안내에 빠졌을 수도 있고, 대표와 고객이 중요하게 보는 점이 다를 수도 있습니다.','실제로 제공하는 가치와 포함·제외 조건을 한 안내에 정리합니다.','고객의 이해와 반복 문의를 먼저 확인합니다. 기대와 실제 제공의 차이가 커지면 문구를 수정합니다.')]
def business():
 b='<div class="ed-wrap"><section class="ed-hero"><div><p class="ed-kicker">WORK WITH DETAIL LAB</p><h1>운영의 고민을,<br><em>움직일 수 있는 일로.</em></h1><p class="ed-lead">무엇이 잘되고 무엇이 막히는지부터 살핍니다. 대표님과 목표를 정하고, 일하는 사람이 이해할 수 있는 기록과 업무 자료로 구체화합니다.</p><div class="ed-actions"><a class="ed-button" href="#contact">내 상황 이야기하기 ↗</a><a class="ed-link" href="/outputs.html">결과물 구성 보기</a></div></div>'+report_preview()+'</section><section class="ed-section" id="approach">'+heading('START WITH THE WORK','같은 질문으로 시작해도,<br>필요한 일은 달라집니다.','직접 적용할 기준이 필요한지, 자료 제작과 사용 점검까지 맡기고 싶은지 구분합니다.')+services()+'</section><section class="ed-section" id="process">'+heading('YOUR EXPERIENCE','문의 후에는,<br>이 순서로 진행합니다.','범위·비용·기간을 확인한 뒤 시작 자료를 전달합니다. 고객이 채울 부분과 디테일랩이 정리할 부분을 나눕니다.')+STEPS+'</section><section class="ed-section" id="deliverables">'+heading('DELIVERABLES','무엇을 받는지,<br>시작 전에 구체적으로.','필요한 결과물을 선택합니다. 아래 자료를 모두 한 번에 제공한다는 의미는 아닙니다.')+'<div class="ed-rows">'
 for n,t,p in [(1,'시작 안내와 사업 이야기','진행 순서와 연락 방식, 고객이 먼저 답할 짧은 질문. 이미 답한 내용은 재사용합니다.'),(2,'운영 정리 리포트','지킬 강점·우선 개선할 일·추가 확인과 판단 이유. 다음 결정이 보이게 정리합니다.'),(3,'목표와 실행 계획','원하는 변화, 이번 작업의 완료 기준, 담당·승인·일정과 다시 볼 지표.'),(4,'현장에서 쓸 업무 자료','한 업무의 고객 안내·역할/승인표·인계표 등 합의한 자료와 사용 설명.'),(5,'적용 후 점검','제작·전달·실제 사용을 구분하고 불편·부작용·다른 원인을 함께 살핍니다.'),(6,'다음 운영을 위한 인계','유지·수정·중단할 일과 최종 버전, 담당과 다음 점검 시점.')]:b+=f'<div class="ed-row"><span>0{n}</span><div><h3>{t}</h3><p>{p}</p></div></div>'
 b+='</div><p><a class="ed-link" href="/outputs.html">고객이 읽는 보고서 구성 살펴보기 →</a></p></section><section class="ed-section" id="cases">'+heading('DIFFERENT CONTEXTS','문제의 이름보다,<br>실제 상황을 봅니다.','아래는 업무 방식을 설명하기 위한 가상 상황입니다. 실제 고객 성과나 후기와 구분합니다.')
 for id,lab,t,info,hyp,act,metric in CASES:b+=f'<article class="ed-case" id="{id}"><p class="ed-kicker">{lab}</p><h3>{t}</h3><dl><dt>먼저 확인</dt><dd>{info}</dd><dt>가능한 설명</dt><dd>{hyp}</dd><dt>구체화할 일</dt><dd>{act}</dd><dt>사용 후 점검</dt><dd>{metric}</dd></dl></article>'
 b+='</section><section class="ed-section" id="responsibility">'+heading('ROLES & RESPONSIBILITIES','목표는 함께 정하고,<br>책임은 분명히 나눕니다.','고객이 원하는 성과와 디테일랩이 완료할 작업은 구분합니다.')+'<div class="ed-grid"><div class="ed-service"><h3>디테일랩이 맡는 일</h3><p>합의한 자료의 검토, 결과물 제작·검수·설명, 정한 범위의 수정과 사용 점검을 맡습니다. 완료 기준과 전달 일정을 시작 전에 확인합니다.</p></div><div class="ed-service"><h3>대표님이 결정할 일</h3><p>목표·예산·내부 기준과 현장 적용을 결정합니다. 자료 제공 권한과 담당자의 협력을 확보하고 중요한 경영 판단과 승인 권한을 갖습니다.</p></div></div><p class="ed-status">새 업무·다른 사업장·추가 제작은 일정과 비용을 다시 안내한 뒤 결정합니다. 무제한 연락이나 상시 운영 대행을 약속하지 않습니다. 전문 자격이 필요한 판단은 해당 전문가의 범위를 확인합니다.</p></section><section class="ed-section" id="data">'+heading('RECORDS & CONTEXT','판단에 쓴 근거와,<br>실제로 달라진 일을 남깁니다.','자료는 목표에 필요한 만큼만 요청합니다. 같은 이름의 지표라도 기간·단위·계산법을 맞춰 봅니다.')+compact_visual()+'<div class="ed-rows"><div class="ed-row"><div><h3>작은 자료부터</h3><p>처음에는 최근 상황을 듣습니다. 추가 파일은 목적·항목·제공 권한·보관·제출 경로를 정한 뒤 받습니다.</p></div></div><div class="ed-row"><div><h3>사람이 최종 확인</h3><p>AI는 허용된 자료의 정리와 초안에 활용할 수 있습니다. 원문·범위·실행 가능성을 사람이 확인합니다.</p></div></div></div><p class="ed-small">현재 홈페이지에는 고객별 로그인·파일 업로드·대시보드·자동 분석 기능이 없습니다. 필요한 시스템 개발과 자료 처리 조건은 별도로 확인합니다.</p><div id="market" class="ed-case"><h3>경제·시장 변화도, 업장 조건과 함께.</h3><p class="ed-lead">금리 뉴스만으로 이자 부담 증가를 단정하지 않습니다. 고정·변동금리와 적용일, 실제 비용을 함께 봅니다. 물가·소비·환율도 고객·원가·가격에 닿는 경로를 확인합니다. 기준일과 발표일을 기록하고 계절·영업일·경쟁 등 다른 설명을 남깁니다.</p></div></section><section class="ed-section">'+CONTACT+'<p class="ed-status">현재는 운영 문의·무료 도구·업종 제한 없는 무료 베타 참여 문의를 이용할 수 있습니다. 기존 센터 베타는 별도로 유지합니다. 맞춤 제작·정기 관리는 결과물·횟수·일정·비용을 개별 확인해 제안하며, 확정 공개 요금제로 판매하고 있지는 않습니다.</p></section></div>'
 return b
def outputs():
 return '''<div class="ed-wrap"><section class="ed-section" style="border-top:0;padding-bottom:0">'''+heading('A REPORT YOU CAN USE','무엇을 봤고,<br>무엇을 할지 보이는 보고서.','고객은 내부 분석 과정을 해석할 필요가 없습니다. 핵심 판단과 이유, 다음 행동이 앞에 오는 구성입니다.')+'''</section><article class="ed-report"><div class="ed-report-head"><span>DETAIL LAB / OPERATIONS REVIEW</span><span>보고서 구성 예시</span></div><p class="ed-small">설명용 가상 사례입니다. 실제 고객의 진단이나 개선 성과가 아닙니다.</p><h1>대표 부재 중 예약 변경,<br>처리 기준부터 정리합니다.</h1><p class="ed-conclusion">연락을 줄이기 전에, 담당자가 처리할 일과 대표가 확인할 예외를 같은 기준으로 정하는 것이 우선입니다.</p><p>대표가 없는 날 예약 변경 요청이 미뤄지는 상황을 가정했습니다. 교대 기록을 남기는 방식은 유지하면서, 판단에 필요한 기준이 문서와 현장 설명에서 일치하는지 먼저 살핍니다.</p><div class="ed-summary"><div><strong>유지</strong><span>교대 때 약속 남기기</span></div><div><strong>우선 정리</strong><span>처리·승인의 경계</span></div><div><strong>다음 확인</strong><span>실제 사용과 고객 혼선</span></div></div><h2>01 현재 상황을 어떻게 봤나요?</h2><div class="ed-finding"><b>유지할 강점</b><p>고객에게 한 약속을 교대 기록에 남긴다는 대표의 설명이 있습니다. 이 기록이 실제로 인계에 사용되는지 확인하고, 유용한 방식은 새 기준에도 남깁니다.</p></div><div class="ed-finding"><b>먼저 보완할 부분</b><p>예약 변경을 담당자가 어디까지 결정할 수 있는지 서로 다르게 이해할 가능성이 있습니다. 모든 연락을 불필요한 연락으로 분류하지 않고, 대표 승인이 필요한 예외와 일상 처리를 나눕니다.</p></div><div class="ed-finding"><b>추가로 확인할 부분</b><p>담당자의 설명과 실제 요청 기록이 아직 없습니다. 업무가 몰린 시간대나 예약 도구 문제로 처리가 늦어진 가능성도 확인해야 합니다. 직원의 태도나 역량으로 원인을 단정하지 않습니다.</p></div><h2>02 이번에 만들 자료는 무엇인가요?</h2><p><b>예약 변경 한 업무의 처리·승인표</b>입니다. 요청 유형, 담당자의 처리 범위, 대표 확인이 필요한 예외, 고객에게 안내할 내용, 교대 시 남길 기록을 정리합니다. 실제 사용자와 대표가 같은 뜻으로 이해하는지 확인한 뒤 적용합니다.</p><div class="table-wrap"><table><thead><tr><th>자료의 항목</th><th>현장에서 답할 질문</th></tr></thead><tbody><tr><td>처리할 수 있는 범위</td><td>어떤 요청을 담당자가 직접 처리하나요?</td></tr><tr><td>대표 확인이 필요한 예외</td><td>어떤 상황에서 결정을 넘기나요?</td></tr><tr><td>고객 안내</td><td>지금 확정할 것과 확인 후 답할 것은 무엇인가요?</td></tr><tr><td>완료와 인계</td><td>누가 처리 결과와 남은 일을 어디에 남기나요?</td></tr></tbody></table></div><h2>03 누가 무엇을 하나요?</h2><div class="table-wrap"><table><thead><tr><th>담당</th><th>맡는 일</th><th>완료 확인</th></tr></thead><tbody><tr><td>디테일랩</td><td>현재 설명 정리, 처리표 제작·설명, 합의한 수정과 사용 점검</td><td>합의한 항목·버전 전달과 설명</td></tr><tr><td>대표</td><td>처리 권한·예외·고객 약속 결정, 현장 적용 승인</td><td>기준과 적용 기간 확인</td></tr><tr><td>현장 담당자</td><td>합의한 기준 사용, 막힌 상황과 인계 기록</td><td>사용 여부와 실제 반응</td></tr></tbody></table></div><h2>04 적용 후 무엇을 확인하나요?</h2><p>요청이 생긴 건수, 대표 확인이 필요했던 건수, 미처리와 잘못된 안내, 실제 처리표 사용을 같은 기간·정의로 남깁니다. 기준선이 없으면 변화율을 만들지 않습니다. 연락이 줄었더라도 고객 혼선이나 업무 누락이 늘면 기준을 수정합니다.</p><div class="ed-finding"><b>다음 점검의 결정</b><p>기준이 실제로 쓰이고 혼선이 없으면 유지합니다. 찾기 어렵거나 설명이 다르면 문장과 위치를 고칩니다. 고객 불편·권한 충돌이 생기면 해당 적용을 멈추고 대표가 복구 범위를 결정합니다.</p></div><p class="ed-small">실제 보고서는 고객의 자료와 합의한 범위에 맞춰 작성합니다. 이 예시의 결론을 다른 업장에 그대로 적용하지 않습니다.</p></article><div class="ed-print-hide ed-actions" style="margin-bottom:70px"><a class="ed-button" href="/business.html#contact">우리 업장 상황 이야기하기 ↗</a><a class="ed-link" href="/business.html#deliverables">받는 자료와 진행 방식</a></div></div>'''

