for path in ROOT.glob('*.html'):
 if path.name in ('index.html','business.html','outputs.html','beta.html'):continue
 text=path.read_text()
 if 'experience-legacy.css' not in text:
  text=text.replace('</head>','<link rel="stylesheet" href="/experience-legacy.css?v=20261110">\n</head>')
  text=re.sub(r'<body([^>]*)>',lambda m:'<body'+(re.sub(r'class="([^"]*)"',r'class="\1 polished"',m[1]) if 'class=' in m[1] else m[1]+' class="polished"')+'>',text,count=1)
 if path.name=='center.html':
  text=text.replace('30일 동안 시험할 행동 1개','30일 동안 적용할 행동 1개').replace('30일 동안 작은 행동 하나를 시험해 볼 곳','30일 동안 작은 행동 하나를 적용해 볼 곳')
 path.write_text(text)
